fn internalStat(s: *Scope, filename: c.JSValue) !c.JSValue {
    try s.pending();
    if (!c.JS_IsString(filename)) return error.ActualInternalModuleStatRequiresString;
    const bytes = try s.engine.toString(filename);
    defer s.engine.gpa.free(bytes);
    try s.pending();
    const namespaced = try @import("native_node_package_path.zig").namespaced(s.engine.gpa, bytes);
    defer s.engine.gpa.free(namespaced);
    // BufferValue is passed to uv_fs_stat as a NUL-terminated native path.
    // No public path validator is inserted into this private C++ boundary.
    const end = std.mem.indexOfScalar(u8, namespaced, 0) orelse namespaced.len;
    const result = try physical.readWithStatus(s.engine.gpa, namespaced[0..end]);
    const code: i32 = switch (result) {
        .metadata => |info| @intFromBool((info.mode & 0o170000) == 0o040000),
        .windows_error => |raw| errors.windowsCode(raw, false),
        .posix_error => |raw| try errors.posixCode(raw),
    };
    try s.pending();
    return c.JS_NewInt32(s.engine.context, code);
}
